#include "context.h"
#include <array>
#include <cstdio>
#include <cstring>
extern "C" void __imp__sub_822CB6A0(PPCContext&, uint8_t*);
extern "C" void sub_822CB6A0(PPCContext&, uint8_t*);

// Synthetic data only: verify the generated byte-fill interface and both guards.
static unsigned test_fill(void (*fill)(PPCContext&, uint8_t*), const char* label) {
    unsigned cases = 0, failures = 0;
    for (unsigned alignment = 0; alignment < 16; ++alignment)
        for (unsigned length = 0; length <= 128; ++length)
            for (unsigned value : {0u, 0x5Au, 0xFFu}) {
                std::array<uint8_t, 256> actual, expected;
                actual.fill(0xC7);
                expected = actual;
                const unsigned address = 32 + alignment;
                std::memset(expected.data() + address, value, length);
                PPCContext ctx{};
                ctx.r3.u64 = address;
                ctx.r4.u64 = value;
                ctx.r5.u64 = length;
                fill(ctx, actual.data());
                ++cases;
                if (actual != expected || ctx.r3.u32 != address) {
                    if (failures < 8) std::printf("Generated fill mismatch: alignment=%u length=%u value=%u\n", alignment, length, value);
                    ++failures;
                }
            }
    std::printf("%s fill: cases=%u failures=%u\n", label, cases, failures);
    return failures;
}

int rrxx_test_generated_fill() {
    const auto generated_failures = test_fill(__imp__sub_822CB6A0, "Generated (diagnostic)");
    const auto compatibility_failures = test_fill(sub_822CB6A0, "Compatibility");
    std::printf("Original defect reproduced=%u; compatibility pass=%u\n",
        generated_failures != 0, compatibility_failures == 0);
    return compatibility_failures ? 1 : 0;
}
